 ): Promise<ArgTypes | null> {
-  const { componentFilePath, componentExportName } = (options ?? {}) as GetArgTypesDataOptions;
+  const { componentFilePath, componentExportName } = options ?? {};

   if (!componentFilePath) {
     return null;
